/**
 * Writes deploy/nginx-seo-redirects.conf from src/content/seo/seoRedirects.js.
 * The live site is served by nginx, which ignores vercel.json, so the old URLs
 * need real 301s in the server block. Include this file inside `server { }`.
 */
import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { SEO_REDIRECTS } from '../src/content/seo/seoRedirects.js';

const out = fileURLToPath(new URL('../deploy/nginx-seo-redirects.conf', import.meta.url));
const lines = [
  '# Generated by `npm run generate:nginx-redirects` — do not edit by hand.',
  '# Source: src/content/seo/seoRedirects.js',
  '# Include inside the ibridge360.com server { } block, above the static `location /`.',
  '',
  ...SEO_REDIRECTS.map(([from, to]) => `location ~ ^${from}/?$ { return 301 ${to}; }`),
  '',
];
writeFileSync(out, lines.join('\n'));
console.log(`Wrote ${SEO_REDIRECTS.length} redirects to deploy/nginx-seo-redirects.conf`);
